"""Value types: translated RhinoCommon bodies (api/valuetypes.json) ->
C++ structs, plus their pybind11 / embind registrations."""

from gen_registry import *
from emit_classes import emit_decl_def, js_class_shape


VT_BANNER = ('// GENERATED by tools/generate/bnd_gen.py from api/valuetypes.json\n'
             '// (tools/specgen translate: RhinoCommon value-type BODIES translated\n'
             '// to C++). DO NOT EDIT. Plain C++: no opennurbs, no binding headers.\n')


def natural_size(t, by_cpp):
    size = 0
    for f in t['Fields']:
        ft = f['Type']
        if ft in by_cpp:
            u = by_cpp[ft]
            size += max(u.get('LayoutSize', 0), natural_size(u, by_cpp))
        else:
            size += {'double': 8, 'long long': 8, 'unsigned long long': 8}.get(ft, 4)
    return size


def vt_file(t):
    return 'gen_%s' % ((t['Cs'] + 'X') if not t['IsStaticClass'] else t['Cs']).lower()


def emit_valuetypes(vt, blocks):
    """One header + one cpp per value type (gen_point3dx.h/.cpp, ...), plus
    gen_vt_common.h (helpers + forward declarations). Headers only DECLARE:
    member declarations may name the other structs by value while still
    incomplete, and fields are plain doubles, so the mutual references
    (Point3d - Point3d -> Vector3d) need no include cycle. Each cpp includes
    every value-type header, so all bodies see complete types. Struct fields
    mirror the C# fields; consts are dependency-ordered; operators are free
    functions declared with their C# declaring type."""
    types = [t for t in vt['types'] if all(f['Type'] for f in t['Fields'])]
    keep = {t['Cs'] for t in types}
    ok = [m for m in vt['members'] if m['Ok'] and m['Type'] in keep]
    # dependency order: a struct's field types are defined first
    order, placed = [], set()
    pending = sorted(types, key=lambda t: (not t['IsStaticClass'], t['Cs']))
    by_cpp0 = {t['Cpp']: t for t in types}
    while pending:
        for t in pending:
            deps = {by_cpp0[f['Type']]['Cs'] for f in t['Fields'] if f['Type'] in by_cpp0} - {t['Cs']}
            if deps <= placed:
                order.append(t); placed.add(t['Cs']); pending.remove(t)
                break
        else:
            raise SystemExit('value-type field cycle')
    files = {}
    files['gen_vt_common.h'] = '\n'.join([
        VT_BANNER, '#pragma once', '#include <cmath>', '#include <limits>',
        '#include <stdexcept>', '#include <type_traits>', '#include <string>', '#include <vector>', '',
        '// C# semantics helpers: Math.Max/Min promote mixed arguments;',
        '// Math.Sign returns int',
        'template <class A, class B> inline typename std::common_type<A, B>::type',
        'RH3DM_Max(A a, B b) { typedef typename std::common_type<A, B>::type T; return T(a) > T(b) ? T(a) : T(b); }',
        'template <class A, class B> inline typename std::common_type<A, B>::type',
        'RH3DM_Min(A a, B b) { typedef typename std::common_type<A, B>::type T; return T(a) < T(b) ? T(a) : T(b); }',
        'template <class A> inline int RH3DM_Sign(A a) { return (a > A(0)) - (a < A(0)); }',
        'inline bool RH3DM_IsPosInf(double x) { return std::isinf(x) && x > 0; }',
        'inline bool RH3DM_IsNegInf(double x) { return std::isinf(x) && x < 0; }',
        '',
        '// Native calls from translated bodies pass structs the way the .NET',
        '// marshaller does: `this`/refs as pointers, values by their bits. The',
        '// translated structs mirror RhinoCommon\'s layout (padding included), so',
        '// they convert to the C parameter types; sizes are checked at compile time.',
        '#include <cstring>',
        '#include <algorithm>',
        '#include <stdexcept>',
        '// System.Array\'s statics on a std::vector, with .NET\'s semantics (G80): ranges',
        '// checked, Copy safe for overlap, LastIndexOf searching back from its start,',
        '// Sort/BinarySearch by the element\'s CompareTo (the default comparer), a',
        '// BinarySearch miss the complement of the insertion point',
        'struct RH3DM_NullComparer { RH3DM_NullComparer(std::nullptr_t = nullptr) {} };',
        '#include <memory>',
        'struct RH3DM_Points;   // SimpleArrayPoint3d (G81): defined in gen_common.h, beside opennurbs',
        '// a data list a call returned, owned here: its items (`new SimpleArrayPoint3d(GetRange(0, Count))`; G81)',
        'template <class T> inline auto RH3DM_OwnedItems(T* p) -> decltype(p->ToArray()) { std::unique_ptr<T> h(p); return h->ToArray(); }',
        'template <class T> inline void RH3DM_ArrCopy(const std::vector<T>& src, int si, std::vector<T>& dst, int di, int n) {',
        '  if (n < 0 || si < 0 || di < 0 || si + n > (int)src.size() || di + n > (int)dst.size()) throw std::out_of_range("Array.Copy");',
        '  if (&src == &dst && di > si) std::copy_backward(src.begin() + si, src.begin() + si + n, dst.begin() + di + n);',
        '  else std::copy(src.begin() + si, src.begin() + si + n, dst.begin() + di); }',
        'template <class T> inline void RH3DM_ArrClear(std::vector<T>& a, int i, int n) {',
        '  if (i < 0 || n < 0 || i + n > (int)a.size()) throw std::out_of_range("Array.Clear");',
        '  std::fill(a.begin() + i, a.begin() + i + n, T{}); }',
        'template <class T> inline int RH3DM_ArrIndexOf(const std::vector<T>& a, const T& x, int i, int n) {',
        '  if (i < 0 || n < 0 || i + n > (int)a.size()) throw std::out_of_range("Array.IndexOf");',
        '  for (int k = i; k < i + n; k++) if (a[k] == x) return k;',
        '  return -1; }',
        'template <class T> inline int RH3DM_ArrLastIndexOf(const std::vector<T>& a, const T& x, int i, int n) {',
        '  if (a.empty() || n == 0) return -1;',
        '  if (i < 0 || n < 0 || i >= (int)a.size() || i - n + 1 < 0) throw std::out_of_range("Array.LastIndexOf");',
        '  for (int k = i; k > i - n; k--) if (a[k] == x) return k;',
        '  return -1; }',
        'template <class T> inline void RH3DM_ArrReverse(std::vector<T>& a, int i, int n) {',
        '  if (i < 0 || n < 0 || i + n > (int)a.size()) throw std::out_of_range("Array.Reverse");',
        '  std::reverse(a.begin() + i, a.begin() + i + n); }',
        'template <class T> inline void RH3DM_ArrSort(std::vector<T>& a, int i, int n, RH3DM_NullComparer = nullptr) {',
        '  if (i < 0 || n < 0 || i + n > (int)a.size()) throw std::out_of_range("Array.Sort");',
        '  std::sort(a.begin() + i, a.begin() + i + n, [](T x, T y) { return x.CompareTo(y) < 0; }); }',
        'template <class T> inline int RH3DM_ArrBinarySearch(const std::vector<T>& a, int i, int n, T x, RH3DM_NullComparer = nullptr) {',
        '  if (i < 0 || n < 0 || i + n > (int)a.size()) throw std::out_of_range("Array.BinarySearch");',
        '  int lo = i, hi = i + n - 1;',
        '  while (lo <= hi) { int mid = lo + ((hi - lo) >> 1); T m = a[mid]; int c = m.CompareTo(x);',
        '    if (c == 0) return mid; if (c < 0) lo = mid + 1; else hi = mid - 1; }',
        '  return ~lo; }',
        'template <class T> struct RH3DM_PtrT { T* p;',
        '  template <class U> operator U*() const {',
        '    static_assert(sizeof(U) == sizeof(T), "value-type layout differs from the C struct");',
        '    return reinterpret_cast<U*>(p); } };',
        'template <class T> inline RH3DM_PtrT<T> RH3DM_Ptr(T* p) { return {p}; }',
        'template <class T> struct RH3DM_ValT { const T& v;',
        '  template <class U> operator U() const {',
        '    static_assert(sizeof(U) == sizeof(T), "value-type layout differs from the C struct");',
        '    U u; std::memcpy(&u, &v, sizeof(U)); return u; } };',
        'template <class T> inline RH3DM_ValT<T> RH3DM_Val(const T& v) { return {v}; }',
        '// an IntPtr a data class hands a native call (G64): the C side types it',
        'struct RH3DM_IPT { void* p; template <class U> operator U*() const { return (U*)p; } };',
        'inline RH3DM_IPT RH3DM_IP(void* p) { return {p}; }',
        '',
        '// RhinoCommon enums the translated bodies use, verbatim (values included)'] + [
        'enum class %s : %s { %s };' % (e['Cpp'], {'int': 'int', 'uint': 'unsigned int', 'byte': 'unsigned char'}.get(e['Underlying'], 'int'),
                                        ', '.join(v['Name'] + (' = ' + v['Value'] if v['Value'] else '') for v in e['Values']))
        for e in vt.get('enums', [])] + [''] + ['struct %s;' % t['Cpp'] for t in order]) + '\n'
    math_hdr = [vt_file(t) + '.h' for t in order if t['IsStaticClass']]
    all_hdrs = ''.join('#include "%s.h"\n' % vt_file(t) for t in order)
    for t in order:
        mine = [m for m in ok if m['Type'] == t['Cs']]
        consts = [m for m in mine if m['Kind'] == 'field-const']
        names = {c['Name'] for c in consts}
        placed, ordered = set(), []
        while len(ordered) < len(consts):
            progress = False
            for c in consts:
                if c['Name'] in placed:
                    continue
                deps = set(re.findall(r'\b(\w+)\b', c['ConstInit'])) & names - {c['Name']}
                if deps <= placed:
                    ordered.append(c); placed.add(c['Name']); progress = True
            if not progress:
                raise SystemExit('const cycle in %s' % t['Cs'])
        h = [VT_BANNER, '#pragma once', '#include "gen_vt_common.h"']
        # default arguments may name RhinoMath constants: it must be complete
        h += ['#include "%s"' % x for x in math_hdr if x != vt_file(t) + '.h']
        by_cpp = {u['Cpp']: u for u in types}
        h += sorted({'#include "%s.h"' % vt_file(by_cpp[f['Type']]) for f in t['Fields']
                     if f['Type'] in by_cpp and by_cpp[f['Type']] is not t})
        by_cs_t = {u['Cs']: u for u in types}
        tbase = by_cs_t.get(t.get('Base'))
        if tbase:
            h.append('#include "%s.h"' % vt_file(tbase))
        # generated classes a data member names (G82): declared here, included by the cpp
        class_deps = sorted({d for m in mine for d in m.get('ClassDeps') or []})
        h += ['class BND_%s;' % d for d in class_deps]
        h += ['', 'struct %s%s\n{' % (t['Cpp'], ' : public %s' % tbase['Cpp'] if tbase else '')]
        if tbase:
            # a name declared here hides the base's overloads in C++ (not in C#): bring them in (G80)
            mine_names = {m['Name'] for m in mine if m['Kind'] == 'method' and m.get('Decl')}
            b = tbase
            while b is not None and mine_names:
                hit = mine_names & {m['Name'] for m in ok if m['Type'] == b['Cs'] and m['Kind'] == 'method' and m.get('Decl')}
                for nm in sorted(hit):
                    h.append('  using %s::%s;' % (b['Cpp'], nm))   # the nearest base: it brings in its own bases' too
                mine_names -= hit
                b = by_cs_t.get(b.get('Base'))
        for f in t['Fields']:
            # a data class field carries RhinoCommon's initializer (G64)
            init = (' = ' + f['Init']) if f.get('Init') else (' = 0' if not f['Type'].startswith(('BND_', 'RH3DM_', 'std::')) else '')
            h.append('  %s %s%s;' % (f['Type'], f['Name'], init))
        pad = t.get('LayoutSize', 0) - natural_size(t, by_cpp)
        if pad > 0:   # RhinoCommon [StructLayout(Size = N)]: e.g. Plane's room for ON_Plane's equation
            assert pad % 8 == 0, (t['Cs'], pad)
            h.append('  double m_rh3dm_pad[%d] = {};   // StructLayout(Size = %d)' % (pad // 8, t['LayoutSize']))
        if not t['IsStaticClass'] and not any(m['Kind'] == 'ctor' and not m.get('Params') and m.get('Decl') for m in mine):
            h.append('  %s() = default;' % t['Cpp'])
        h += ['  ' + c['Decl'] for c in ordered]
        h += ['  ' + m['Decl'] for m in mine
              if m['Kind'] not in ('field-const', 'field', 'operator') and m['Decl']]
        h.append('};\n')
        h += [m['Decl'] for m in mine if m['Kind'] == 'operator']
        files[vt_file(t) + '.h'] = '\n'.join(h) + '\n'

        native = any(m.get('Native') for m in mine)
        cpp = [VT_BANNER, all_hdrs + ('#include "gen_common.h"   // C declarations for native calls\n'
                                      if native else '')]
        cpp += ['#include "gen_%s.h"\n' % d.lower() for d in class_deps]
        cpp += [m['Def'] + '\n' for m in mine if m.get('Def')]
        if t['Cs'] in blocks:
            py_block, js_tag, js_block = blocks[t['Cs']]
            reg = t['Cs'] + 'X'
            cpp.append(''.join('#include "%s"\n' % h for h in sorted(BRIDGE_INCLUDES.get(t['Cs'], ())))
                       + '''#include "gen_common.h"

#if defined(ON_PYTHON_COMPILE)
void initGen{reg}(rh3dmpymodule& m)
{{
{py}
}}
#endif

#if defined(ON_WASM_COMPILE)
using namespace emscripten;
{tag}
void initGen{reg}(void)
{{
{js}
}}
#endif
'''.format(reg=reg, py=py_block, tag=js_tag, js=js_block))
        files[vt_file(t) + '.cpp'] = '\n'.join(cpp)
    return files


def pub(m, expr):
    """a translated member returning a translated enum hands the binding
    the PUBLICLY registered enum (the old bindings own TransformSimilarityType
    etc. today): RH3DM_Pub casts; every other return passes through. A
    std::vector result (G70) is marked: Python takes it as a list (stl.h),
    JS gets an array (RH3DM_JsArray) -- resolved per side at the end"""
    if (m.get('Ret') or '').startswith('std::vector<'):
        return '@@VEC@@(%s)' % expr
    return 'RH3DM_Pub(%s)' % expr if m.get('Ret') in VT_ENUMS else expr


def emit_valuetype_bindings(vt, skipped):
    """Python: real classes (pybind objects are garbage-collected), RhinoCommon
    members only, plus language protocols -- operators from the C# operators,
    repr, a sequence constructor and implicit conversion from tuple/list.
    JS: embind value_object, so a value is a plain garbage-collected
    {X, Y, Z} object (no wasm-heap instance, no .delete()); behavior is
    exposed as functions, rhino.Point3dX.DistanceTo(p, q), and mutating
    members return the new value since a JS value is a copy."""
    blocks = {}   # C# type -> (py block, js tag decl, js block)
    # the JS property identifying a value object's shape: its first field's
    # field-backed property name (m_x -> X, m_t0 -> T0, m_origin -> Origin)
    js_key = {}
    for t in vt['types']:
        if t['IsStaticClass'] or not t['Fields']:
            continue
        f0 = t['Fields'][0]['Name']
        js_key[t['Cpp']] = field_backed(vt, t['Cs']).get(f0, f0)
    for t in vt['types']:
        if t['IsStaticClass']:
            continue
        T, cs = t['Cpp'], t['Cs']
        reg = cs + 'X'
        if t.get('IsData'):
            blocks[cs] = emit_data_bindings(t, vt, skipped)
            continue
        fields = [f['Name'] for f in t['Fields']]
        mine = [m for m in vt['members'] if m['Type'] == cs and m['Ok'] and m['Public']]
        # overloads a binding cannot tell apart (same INPUT parameters; they
        # differ only in out-param order, DecomposeAffine): the first one
        # registered wins, so register them in the shared rule's order --
        # lowest parameter-type sequence, as the class planner and the .NET
        # oracle do. Overloads with distinct inputs keep their order.
        def inkey(m):
            return (m['Name'], m['Static'], m['Kind'],
                    tuple(q['Type'] for q in m['Params'] or [] if not q['Mode']))
        groups = {}
        for m in mine:
            groups.setdefault(inkey(m), []).append(m)
        dotnet = dict({v: k for k, v in VT_CPP.items()},
                      double='Double', int='Int32', bool='Boolean')   # Type.Name, as the oracle sorts
        for g in groups.values():
            g.sort(key=lambda m: ','.join(dotnet.get(q['Type'].rstrip('&'), q['Type'])
                                          for q in m['Params'] or []))
        mine = [groups[inkey(m)].pop(0) for m in mine]
        props = {m['Name'] for m in mine if m['Kind'] == 'property'}
        # a property is field-backed when its translated body IS the field
        field_of = {f: p for f, p in field_backed(vt, cs).items() if p in props}
        pyl = ['  py::class_<%s>(m, "%s")' % (T, reg), '      .def(py::init<>())']
        jsl = []

        def sig(m):
            return ', '.join('%s %s' % (p['Type'], p['Name']) for p in m['Params'] or [])

        def names(m):
            return ', '.join(p['Name'] for p in m['Params'] or [])

        def pyargs(m):
            return ''.join(', py::arg("%s")' % p['Name'] for p in m['Params'] or [])

        # JS functions are collected per (name, arity) and emitted after the
        # loop: embind keeps ONE function per name+arity, so same-arity
        # overloads (Point3d*double vs double*Point3d, Vector3d*Vector3d dot)
        # get a generated C++ dispatcher on argument shape instead of the
        # first one silently winning (generator-log G5). Bodies use a0..aN.
        js_entries = {}

        def js_fn(name, types, body):
            js_entries.setdefault((name, len(types)), []).append((types, body))

        instance_names = {m['Name'] for m in mine if not m['Static'] and m['Kind'] == 'method'}
        for m in mine:
            k, n = m['Kind'], m['Name']
            if k != 'ctor' and any(p['Type'] in VT_ENUMS for p in m['Params'] or []):
                # a translated-enum PARAMETER outside a constructor: not needed yet
                skipped['value-type enum param'] = skipped.get('value-type enum param', 0) + 1
                continue
            if k == 'method' and m['Static'] and n in instance_names:
                # Python cannot overload one name as static AND instance
                # (BoundingBox.Union(a, b) vs bbox.Union(other)): the instance
                # form keeps the name; counted, and still reachable in JS
                skipped['py static shadowed by instance'] = skipped.get('py static shadowed by instance', 0) + 1
                js_fn(n, [p['Type'] for p in m['Params']],
                      'return %s::%s(%s);' % (T, n, ', '.join('a%d' % i for i in range(len(m['Params'])))))
                continue
            if any(p['Mode'] for p in m['Params'] or []):
                # out-parameters: Python gets a tuple, JS an array -- (return,
                # out1, ...) like the generated class members
                if k != 'method' or any(p['Mode'] == 'ref' for p in m['Params']):
                    skipped['value-type ref param'] = skipped.get('value-type ref param', 0) + 1
                    continue
                ins = [p for p in m['Params'] if not p['Mode']]
                outs = [p for p in m['Params'] if p['Mode'] == 'out']
                callargs = ', '.join(p['Name'] for p in m['Params'])
                locs = ' '.join('%s %s{};' % (p['Type'], p['Name']) for p in outs)
                recv = ('%s::' % T) if m['Static'] else 'self.'
                selfp = [] if m['Static'] else ['%s& self' % T]
                sig_in = ', '.join(selfp + ['%s %s' % (p['Type'], p['Name']) for p in ins])
                has_ret = m['Ret'] != 'void'
                vals = (['r'] if has_ret else []) + [p['Name'] for p in outs]
                call = '%s%s(%s)' % (recv, n, callargs)
                body_call = ('auto r = %s;' % pub(m, call)) if has_ret else ('%s;' % call)
                pyl.append('      .def%s("%s", [](%s) { %s %s return py::make_tuple(%s); }%s)'
                           % ('_static' if m['Static'] else '', n, sig_in, locs, body_call,
                              ', '.join(vals), ''.join(', py::arg("%s")' % p['Name'] for p in ins)))
                jtypes = ([] if m['Static'] else [T]) + [p['Type'] for p in ins]
                jnames = {p['Name']: 'a%d' % (i + (0 if m['Static'] else 1)) for i, p in enumerate(ins)}
                jcall = '%s%s(%s)' % ('%s::' % T if m['Static'] else 'a0.', n,
                                      ', '.join(jnames.get(p['Name'], p['Name']) for p in m['Params']))
                js_fn(n, jtypes, '%s %s emscripten::val arr = emscripten::val::array(); %s return arr;'
                      % (locs, ('auto r = %s;' % pub(m, jcall)) if has_ret else ('%s;' % jcall),
                         ' '.join('arr.call<void>("push", %s);' % v for v in vals)))
                continue
            if k == 'ctor' and m['Decl'] and any(p['Type'] in VT_ENUMS for p in m['Params']):
                # `ComponentIndex(ComponentIndexType type, int index)`: the binding
                # takes the PUBLICLY registered enum and casts it to the translated
                # one, as RH3DM_Pub does for returns
                ptypes = [VT_ENUMS.get(p['Type'], p['Type']) for p in m['Params']]
                def priv(p, a):
                    return '(%s)(int)%s' % (p['Type'], a) if p['Type'] in VT_ENUMS else a
                pyl.append('      .def(py::init([](%s) { return %s(%s); })%s)'
                           % (', '.join('%s %s' % (t, p['Name']) for t, p in zip(ptypes, m['Params'])), T,
                              ', '.join(priv(p, p['Name']) for p in m['Params']), pyargs(m)))
                js_fn('Create', ptypes, 'return %s(%s);'
                      % (T, ', '.join(priv(p, 'a%d' % i) for i, p in enumerate(m['Params']))))
            elif k == 'ctor':
                if m['Decl']:
                    pyl.append('      .def(py::init<%s>()%s)'
                               % (', '.join(p['Type'] for p in m['Params']), pyargs(m)))
                    # JS values are plain objects, which cannot have constructors:
                    # RhinoCommon's constructors become Create(...) (one rule)
                    js_fn('Create', [p['Type'] for p in m['Params']],
                          'return %s(%s);' % (T, ', '.join('a%d' % i for i in range(len(m['Params'])))))
                else:
                    pyl.append('      .def(py::init<const %s&>())' % T)
            elif k == 'method' and m['Static']:
                pyl.append('      .def_static("%s", [](%s) { return %s; }%s)'
                           % (n, sig(m), pub(m, '%s::%s(%s)' % (T, n, names(m))), pyargs(m)))
                js_fn(n, [p['Type'] for p in m['Params']],
                      'return %s;' % pub(m, '%s::%s(%s)' % (T, n, ', '.join('a%d' % i for i in range(len(m['Params']))))))
            elif k == 'method':
                self_sig = ', '.join(['%s& self' % T] + ([sig(m)] if sig(m) else []))
                pyl.append('      .def("%s", [](%s) { return %s; }%s)'
                           % (n, self_sig, pub(m, 'self.%s(%s)' % (n, names(m))), pyargs(m)))
                types = [T] + [p['Type'] for p in m['Params']]
                call = 'a0.%s(%s)' % (n, ', '.join('a%d' % (i + 1) for i in range(len(m['Params']))))
                if m['Ret'] == 'void':     # mutator: a JS value is a copy -> return it
                    js_fn(n, types, '%s; return a0;' % call)
                elif m.get('Mutates'):     # mutates AND returns: both (generator-log G6)
                    js_fn(n, types, 'auto r = %s; emscripten::val o = emscripten::val::object(); '
                                    'o.set("self", a0); o.set("returns", r); return o;' % pub(m, call))
                else:
                    js_fn(n, types, 'return %s;' % pub(m, call))
            elif k in ('property', 'static-field') and m['Static']:
                pyl.append('      .def_property_readonly_static("%s", [](py::object) { return %s::%s(); })'
                           % (n, T, m['Getter']))
                js_fn(n, [], 'return %s::%s();' % (T, m['Getter']))
                JS_POST['static_props'].append((reg, n))      # a getter in JS (G101), as in C#/Python
            elif k == 'property':
                get = '[](%s& s) { return %s; }' % (T, pub(m, 's.%s()' % m['Getter']))
                if m.get('Setter'):
                    pyl.append('      .def_property("%s", %s, [](%s& s, %s v) { s.%s(v); })'
                               % (n, get, T, m['Ret'], m['Setter']))
                else:
                    pyl.append('      .def_property_readonly("%s", %s)' % (n, get))
                if n not in field_of.values():          # field-backed: a plain JS field
                    js_fn(n, [T], 'return %s;' % pub(m, 'a0.%s()' % m['Getter']))
            elif k == 'indexer' and len(m['Params']) == 2:
                # xf[0, 1]: Python hands __getitem__ ONE tuple -> std::pair
                a, b = [q['Name'] for q in m['Params']]
                pyl.append('      .def("__getitem__", [](%s& s, std::pair<int, int> ij) { return s.get_Item(ij.first, ij.second); })' % T)
                if m.get('Setter'):
                    pyl.append('      .def("__setitem__", [](%s& s, std::pair<int, int> ij, %s value) { s.set_Item(ij.first, ij.second, value); })'
                               % (T, m['Ret']))
            elif k == 'indexer':
                pyl.append('      .def("__getitem__", [](%s& s, %s) { return s.get_Item(%s); })'
                           % (T, sig(m), names(m)))
                if m.get('Setter'):
                    pyl.append('      .def("__setitem__", [](%s& s, %s, %s value) { s.set_Item(%s, value); })'
                               % (T, sig(m), m['Ret'], names(m)))
            elif k == 'operator':
                ps = m['Params']
                key = (m['Op'], len(ps))
                if key not in PY_OPS:
                    skipped['value-type operator %s' % m['Op']] = 1
                    continue
                dunder = PY_OPS[key]
                if len(ps) == 1:
                    pyl.append('      .def("__%s__", [](%s a) { return %sa; }, py::is_operator())'
                               % (dunder, ps[0]['Type'], m['Op']))
                elif ps[0]['Type'] == T:
                    pyl.append('      .def("__%s__", [](%s a, %s b) { return a %s b; }, py::is_operator())'
                               % (dunder, ps[0]['Type'], ps[1]['Type'], m['Op']))
                else:                                   # other type on the left: reflected
                    pyl.append('      .def("__r%s__", [](%s b, %s a) { return a %s b; }, py::is_operator())'
                               % (dunder, ps[1]['Type'], ps[0]['Type'], m['Op']))
                js_fn(CS_OP_NAMES[key], [p['Type'] for p in ps],
                      ('return %sa0;' % m['Op']) if len(ps) == 1 else ('return a0 %s a1;' % m['Op']))

        # ONE definition of how a JS value is recognized, shared with the
        # class dispatchers (emit_classes.js_class_shape): {X,Y,Z} keyed on Z,
        # {X,Y} must lack Z -- the value-type copy had drifted (generator-log G22)
        def js_check(v, t):
            return js_class_shape(t)[1].format(v=v)

        def js_shape(t):
            return js_class_shape(t)[0]

        def js_vectors(types, body):
            """a std::vector parameter arrives as a JS array (emscripten::val),
            converted first; a vector result goes out as one (G70)"""
            conv = []
            types2 = []
            for i, t in enumerate(types):
                if t.startswith('std::vector<'):
                    conv.append('%s a%d_v = RH3DM_JsSeq<%s>(a%d);' % (t, i, t[len('std::vector<'):-1], i))
                    body = re.sub(r'\ba%d\b' % i, 'a%d_v' % i, body)
                    types2.append('emscripten::val')
                else:
                    types2.append(t)
            return types2, ' '.join(conv) + (' ' if conv else '') + body.replace('@@VEC@@(', 'RH3DM_JsArray(')

        for (fname, arity), ents in js_entries.items():
            # overloads JS cannot tell apart (Point3d+Point3d vs Point3d+Vector3d:
            # both {X,Y,Z}) collapse to the first -- a dispatcher could never
            # pick another, it would only cost a shape check per call
            by_shape = {}
            for e in ents:
                by_shape.setdefault(tuple(js_shape(t) for t in e[0]), e)
            ents = list(by_shape.values())
            ents = [js_vectors(types, body) for types, body in ents]
            if len(ents) == 1:
                types, body = ents[0]
                params = ', '.join('%s a%d' % (t, i) for i, t in enumerate(types))
                jsl.append('      .class_function("%s", optional_override([](%s) { %s }))'
                           % (fname, params, body))
                continue
            # dispatcher: first overload whose argument shapes match. Shapes
            # that JS cannot tell apart (Point3d vs Vector3d are both {X,Y,Z})
            # resolve to the first -- same numbers for every such pair here.
            vparams = ', '.join('emscripten::val v%d' % i for i in range(arity))
            branches = []
            for types, body in ents:
                cond = ' && '.join(js_check('v%d' % i, t) for i, t in enumerate(types)) or 'true'
                conv = ' '.join('%s a%d = v%d.as<%s>();' % (t, i, i, t) for i, t in enumerate(types))
                branches.append('if (%s) { %s return emscripten::val([&]() { %s }()); }'
                                % (cond, conv, body))
            jsl.append('      .class_function("%s", optional_override([](%s) -> emscripten::val {\n'
                       '        %s\n        throw std::invalid_argument("%s.%s: no overload matches the arguments"); }))'
                       % (fname, vparams, '\n        '.join(branches), reg, fname))
            skipped['js value-type dispatcher'] = skipped.get('js value-type dispatcher', 0) + 1

        # value type -> class conversions (Sphere.ToBrep() =>
        # Brep.CreateFromSphere(this)): the translated C++ cannot name a class,
        # so the BINDING calls the generated class static the C# body calls
        have = {m['Name'] for m in mine}
        for x in BRIDGE_CANDIDATES.get(cs, []):
            cls_cs, stat = x['Delegates'].split('.')
            dargs = x.get('DelegateArgs') or []
            if x['Name'] in have or not dargs or dargs[0]['Text'] != 'this' \
                    or any(a['Kind'] != 'param' for a in dargs[1:]):
                continue
            pnames = [a['Text'] for a in dargs[1:]]
            ptypes = {q['Name']: q['Type'] for q in x.get('Params') or []}
            if set(pnames) != set(ptypes) or any(q.get('Mode') for q in x.get('Params') or []):
                continue
            want = [T] + [CS_ARG.get(ptypes[n], (VT_CPP.get(ptypes[n]),))[0] for n in pnames]
            hit = [q for q in BRIDGE_STATICS.get((cls_cs, stat), [])
                   if [t for t, _ in q['bind_args']] == want]
            if len(hit) != 1:
                continue
            q, target = hit[0], BY_CS[cls_cs]
            sig_rest = ''.join(', %s %s' % (t, n) for t, n in zip(want[1:], pnames))
            call = '%s::%s(self%s)' % (target['gen'], q['cpp'], ''.join(', ' + n for n in pnames))
            pyl.append('      .def("%s", [](%s& self%s) { return %s; }%s)'
                       % (x['Name'], T, sig_rest, call, ''.join(', py::arg("%s")' % n for n in pnames)))
            jsl.append('      .class_function("%s", optional_override([](%s a0%s) { return %s::%s(%s); }), allow_raw_pointers())'
                       % (x['Name'], T, ''.join(', %s a%d' % (t, i + 1) for i, t in enumerate(want[1:])),
                          target['gen'], q['cpp'], ', '.join('a%d' % i for i in range(len(want)))))
            BRIDGE_INCLUDES.setdefault(cs, set()).add('gen_%s.h' % target['reg'].lower())
            have.add(x['Name'])
            skipped['value-type -> class bridge'] = skipped.get('value-type -> class bridge', 0) + 1

        # protocols: sequence construction (+ implicit tuple/list), repr
        nf = len(fields)
        all_double = all(f['Type'] == 'double' for f in t['Fields'])
        if all_double: pyl.append('      .def(py::init([](py::sequence s) {\n'
                   '        if (py::len(s) != %d) throw py::value_error("%s needs %d values");\n'
                   '        %s v;\n%s        return v; }))'
                   % (nf, reg, nf, T, ''.join('        v.%s = s[%d].cast<double>();\n' % (f, i)
                                              for i, f in enumerate(fields))))
        pyl.append('      .def("__repr__", [](const %s& v) { return py::str("%s(%s)").format(%s); });'
                   % (T, reg, ', '.join(['{}'] * nf), ', '.join('v.%s' % f for f in fields)))
        if all_double:
            pyl.append('  py::implicitly_convertible<py::tuple, %s>();' % T)
            pyl.append('  py::implicitly_convertible<py::list, %s>();' % T)
        else:
            pyl[-1] = pyl[-1]     # struct-of-structs: constructed from its C# constructors only
        py_block = '\n'.join(pyl)

        vfields = []
        for f in fields:
            if f in field_of or f not in VALUE_FIELD_PROPS.get(cs, {}):
                if f not in field_of:
                    raise SystemExit('%s.%s: a JS value-object field with no RhinoCommon name -- add it to '
                                     'VALUE_FIELD_PROPS (gen_registry)' % (cs, f))
                vfields.append('      .field("%s", &%s::%s)' % (field_of[f], T, f))
                continue
            for pp in VALUE_FIELD_PROPS[cs][f]:
                name, other = (pp if isinstance(pp, tuple) else (pp, None))
                pm = next((m for m in mine if m['Kind'] == 'property' and m['Name'] == name and not m['Static']), None)
                if pm is None or (other is None and not pm.get('Setter')) or (other is not None and other not in fields):
                    raise SystemExit('%s.%s: VALUE_FIELD_PROPS names %s, not a get/set property here' % (cs, f, name))
                rt = pm['Ret']
                # a translated enum crosses as the PUBLIC enum JS registers (RH3DM_Pub / its cast back)
                pt, back = (VT_ENUMS[rt], '(%s)(int)v' % rt) if rt in VT_ENUMS else (rt, 'v')
                setter = ('[](%s& s, %s v) { s.%s(%s); }' % (T, pt, pm['Setter'], back) if other is None
                          else '[](%s& s, %s v) { s = %s(%s, s.%s); }' % (T, pt, T, back, other))
                vfields.append('      .field("%s", +[](const %s& s) { return %s; }, +%s)'
                               % (name, T, pub(pm, 's.%s()' % pm['Getter']), setter))
        vo = ('  value_object<%s>("%sValue")\n%s;' % (T, reg, '\n'.join(vfields)))
        tag = 'RH3DM_%sFns' % reg
        py_block = py_block.replace('@@VEC@@(', '(')
        blocks[cs] = (py_block, 'struct %s {};' % tag,
                      vo + '\n  class_<%s>("%s")\n%s;' % (tag, reg, '\n'.join(jsl)))

    return blocks


# a generic data base read for one element type (G80) is a C++ base only: its
# members are bound on the first registered class deriving from it
MONO_BASES = {'RhinoList'}


def data_chain(t, vt):
    """t and the data classes it derives from, nearest first (G80)"""
    by = {u['Cs']: u for u in vt['types']}
    out = []
    while t is not None:
        out.append(t)
        t = by.get(t.get('Base'))
    return out


def emit_data_bindings(t, vt, skipped):
    """a DATA class (G64: ConstructionPlane, File3dmWriteOptions; G80: Point3dList,
    Polyline): a real class in both languages -- constructed, mutated in place,
    nullable -- never a value object. Members are RhinoCommon's public ones;
    translated enums cross the boundary as the registered public enum (RH3DM_Pub
    and its inverse). G80 adds constructors with arguments, statics, the
    indexer as the language's item protocol (Python __getitem__/__setitem__/__len__,
    JS get/set), sequences in (a Python sequence / JS array) and out (list /
    array), data objects out (owned by the caller), and inheritance: a class
    deriving from a registered data class is registered on it; members of an
    unregistered generic base (RhinoList) are bound on its first registered
    subclass."""
    T, cs = t['Cpp'], t['Cs']
    reg = cs + 'X'
    if cs in MONO_BASES:
        return '', '', ''
    chain = data_chain(t, vt)
    base = chain[1] if len(chain) > 1 and chain[1]['Cs'] not in MONO_BASES else None
    # this class's members, and those of unregistered bases between it and the next registered one
    own = [t['Cs']] + [u['Cs'] for u in chain[1:] if u['Cs'] in MONO_BASES and (base is None or chain.index(u) < chain.index(base))]
    mine = [m for m in vt['members'] if m['Type'] in own and m['Ok'] and m['Public']]
    # a derived declaration hides the base's member of that name and arity
    seen, ordered = set(), []
    for c in own:
        for m in (x for x in mine if x['Type'] == c):
            key = (m['Kind'], m['Name'], len(m.get('Params') or []))
            if m['Kind'] == 'ctor' and c != t['Cs']:
                continue                               # constructors are not inherited
            if key in seen and m['Kind'] != 'ctor':
                continue
            seen.add(key)
            ordered.append(m)
    mine = ordered
    data_cpp = {u['Cpp']: u['Cs'] for u in vt['types'] if u.get('IsData')}
    class_gens = {c['gen'] for c in CLASSES}           # a generated class a data member returns (G82)
    registered = lambda cpp: (cpp in data_cpp and data_cpp[cpp] not in MONO_BASES) or cpp in class_gens

    def pub_t(ty):
        return VT_ENUMS.get(ty, ty)

    def priv(ty, expr):
        return '(%s)(int)%s' % (ty, expr) if ty in VT_ENUMS else expr

    def ret(ty, expr):
        return 'RH3DM_Pub(%s)' % expr if ty in VT_ENUMS else expr

    def bindable(m):
        """the shapes a binding can carry: no out/ref, no comparer (decision 3), data
        objects only of registered classes"""
        ps = m.get('Params') or []
        if any(q.get('Mode') for q in ps) or any(q['Type'] == 'RH3DM_NullComparer' for q in ps):
            return False
        # a sequence the body WRITES (CopyTo(array)): the caller's list would be a copy
        if re.search(r'(?<!const )std::vector<[^>]*>&', m.get('Decl') or ''):
            return False
        r = (m.get('Ret') or '')
        if r.endswith('*') and not registered(r[:-1]):
            return False
        return not any(q['Type'].rstrip('*') in data_cpp and not registered(q['Type'].rstrip('*')) for q in ps)

    pyl = ['  py::class_<%s%s>(m, "%s")' % (T, (', ' + base['Cpp']) if base else '', reg)]
    jsl = ['  class_<%s%s>("%s")' % (T, (', base<%s>' % base['Cpp']) if base else '', reg)]
    if cs_enumerable(t['Cs']):
        JS_POST['enumerable'].append(reg)                 # a RhinoList: for...of in JS (G101)
    ctors = [m for m in mine if m['Kind'] == 'ctor' and m.get('Decl') and bindable(m)]
    if not any(not (m.get('Params') or []) for m in ctors):
        ctors.insert(0, {'Params': []})              # the implicit default constructor
    js_ctor_arity = set()
    # same-arity constructors (Point3dList(int capacity) / (IEnumerable<Point3d> points)): one JS
    # constructor dispatching on argument shape -- before, all but the first were dropped, and
    # `new Point3dListX([p, p, p])` silently took the capacity constructor (an empty list)
    from emit_classes import js_class_shape, js_shadowed, js_branch_order
    by_arity = {}
    for m in ctors:
        by_arity.setdefault(len(m.get('Params') or []), []).append(m)
    def jt(q):
        return 'const %s&' % q['Type'] if q['Type'].startswith('std::vector<') else pub_t(q['Type'])
    for m in ctors:
        ps = m.get('Params') or []
        pyl.append('      .def(py::init<%s>()%s)' % (', '.join(jt(q) for q in ps),
                                                    ''.join(', py::arg("%s")' % q['Name'] for q in ps)))
        if len(ps) in js_ctor_arity:
            continue
        group = by_arity[len(ps)]
        if len(group) > 1:
            group = sorted(group, key=lambda g: js_branch_order(None, [jt(q) for q in g.get('Params') or []]))
            shd = js_shadowed([[js_class_shape(jt(q))[0] for q in g.get('Params') or []] for g in group])
            if shd:
                raise SystemExit('%s constructor/%d: JS dispatcher branch unreachable: %s' % (reg, len(ps), shd))
            branches = []
            for g in group:
                shapes = [js_class_shape(jt(q)) for q in g['Params']]
                cond = ' && '.join(sh[1].format(v='v%d' % i) for i, sh in enumerate(shapes))
                args = ', '.join(sh[2].format(v='v%d' % i) for i, sh in enumerate(shapes))
                branches.append('if (%s) return new %s(%s);' % (cond, T, args))
            jsl.append('      .constructor(optional_override([](%s) -> %s* {\n        %s\n'
                       '        throw std::invalid_argument("%s: no constructor matches the arguments"); }), allow_raw_pointers())'
                       % (', '.join('emscripten::val v%d' % i for i in range(len(ps))), T, '\n        '.join(branches), reg))
            js_ctor_arity.add(len(ps))
            continue
        if not ps:
            jsl.append('      .constructor<>()')
        elif any(q['Type'].startswith('std::vector<') for q in ps):
            # a sequence argument: a JS array, converted (G80)
            vps = ', '.join(('emscripten::val a%d' if q['Type'].startswith('std::vector<') else pub_t(q['Type']) + ' a%d') % i for i, q in enumerate(ps))
            args = ', '.join(('RH3DM_JsSeq<%s>(a%d)' % (q['Type'][len('std::vector<'):-1], i)) if q['Type'].startswith('std::vector<') else 'a%d' % i for i, q in enumerate(ps))
            jsl.append('      .constructor(optional_override([](%s) { return new %s(%s); }), allow_raw_pointers())' % (vps, T, args))
        else:
            jsl.append('      .constructor<%s>()' % ', '.join(pub_t(q['Type']) for q in ps))
        js_ctor_arity.add(len(ps))
    has_count = any(m['Kind'] == 'property' and m['Name'] == 'Count' and not m.get('Static') for m in mine)
    for m in mine:
        k, n = m['Kind'], m['Name']
        if k == 'ctor':
            continue
        if not bindable(m):
            skipped['data-class member shape'] = skipped.get('data-class member shape', 0) + 1
            continue
        if k == 'property' and not m.get('Static'):
            getter = '[](const %s& s) { return %s; }' % (T, ret(m['Ret'], 's.%s()' % m['Getter']))
            if m['Ret'].startswith('std::vector<'):
                getter = '[](%s& s) { return s.%s(); }' % (T, m['Getter'])
            if m.get('Setter'):
                setter = '[](%s& s, %s v) { s.%s(%s); }' % (T, pub_t(m['Ret']), m['Setter'], priv(m['Ret'], 'v'))
                pyl.append('      .def_property("%s", %s, %s)' % (n, getter, setter))
                if m['Ret'] not in VT_ENUMS:
                    jsl.append('      .property("%s", &%s::%s, &%s::%s)' % (camel(n), T, m['Getter'], T, m['Setter']))
                else:
                    skipped['js data-class enum property'] = skipped.get('js data-class enum property', 0) + 1
            else:
                pyl.append('      .def_property_readonly("%s", %s)' % (n, getter))
                if m['Ret'].startswith('std::vector<'):
                    jsl.append('      .function("%s", optional_override([](%s& s) { return RH3DM_JsArray(s.%s()); }))' % (camel(n), T, m['Getter']))
                elif m['Ret'] not in VT_ENUMS:
                    jsl.append('      .property("%s", &%s::%s)' % (camel(n), T, m['Getter']))
                else:
                    skipped['js data-class enum property'] = skipped.get('js data-class enum property', 0) + 1
            if n == 'Count' and has_count:
                pyl.append('      .def("__len__", [](const %s& s) { return s.%s(); })' % (T, m['Getter']))
        elif k == 'indexer' and len(m.get('Params') or []) == 1:
            # the item protocol (G80); an out-of-range index throws (IndexError)
            q = m['Params'][0]
            pyl.append('      .def("__getitem__", [](%s& s, %s i) { return s.%s(i); })' % (T, q['Type'], m['Getter']))
            jsl.append('      .function("get", optional_override([](%s& s, %s i) { return s.%s(i); }))' % (T, q['Type'], m['Getter']))
            if m.get('Setter'):
                pyl.append('      .def("__setitem__", [](%s& s, %s i, %s v) { s.%s(i, v); })' % (T, q['Type'], m['Ret'], m['Setter']))
                jsl.append('      .function("set", optional_override([](%s& s, %s i, %s v) { s.%s(i, v); }))' % (T, q['Type'], m['Ret'], m['Setter']))
        elif k == 'method':
            ps = m['Params'] or []
            st = bool(m.get('Static'))
            sig = ', '.join('%s %s' % (pub_t(q['Type']) if not q['Type'].startswith('std::vector<') else 'const %s&' % q['Type'], q['Name']) for q in ps)
            call = '%s%s(%s)' % ('%s::' % T if st else 's.', n, ', '.join(priv(q['Type'], q['Name']) for q in ps))
            r = m['Ret']
            pybody = ('%s;' % call) if r == 'void' else ('return %s;' % ret(r, call))
            self_p = '' if st else '%s& s%s' % (T, ', ' if ps else '')
            pyl.append('      .%s("%s", [](%s%s) { %s }%s%s)'
                       % ('def_static' if st else 'def', n, self_p, sig, pybody,
                          ''.join(', py::arg("%s")' % q['Name'] for q in ps),
                          ', py::return_value_policy::take_ownership' if r.endswith('*') else ''))
            # JS: sequences in as arrays, out as arrays
            jps, conv = [], []
            for q in ps:
                if q['Type'].startswith('std::vector<'):
                    jps.append('emscripten::val %s_js' % q['Name'])
                    conv.append('%s %s = RH3DM_JsSeq<%s>(%s_js);' % (q['Type'], q['Name'], q['Type'][len('std::vector<'):-1], q['Name']))
                else:
                    jps.append('%s %s' % (pub_t(q['Type']), q['Name']))
            jcall = call if not r.startswith('std::vector<') else 'RH3DM_JsArray(%s)' % call
            jbody = ' '.join(conv + [('%s;' % jcall) if r == 'void' else ('return %s;' % ret(r, jcall))])
            jself = '' if st else '%s& s%s' % (T, ', ' if jps else '')
            jsl.append('      .%s("%s", optional_override([](%s%s) { %s })%s)'
                       % ('class_function' if st else 'function', camel(n), jself, ', '.join(jps), jbody,
                          ', allow_raw_pointers()' if r.endswith('*') else ''))
        else:
            skipped['data-class member kind %s' % k] = skipped.get('data-class member kind %s' % k, 0) + 1
    pyl[-1] += ';'
    jsl[-1] += ';'
    return '\n'.join(pyl), '', '\n'.join(jsl)
